// Generates the TypeScript client in src/generated from the Anchor IDLs.
//
//   pnpm generate          copy target/idl/*.json into idl/, then render src/generated
//   pnpm generate --no-copy  render from the committed idl/ only (used by check.ts)
//   pnpm generate --out <dir>  render into <dir>/<program> instead of src/generated
//
// Run it after `anchor build`. Never edit src/generated by hand.

import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { rootNodeFromAnchor, type AnchorIdl } from "@codama/nodes-from-anchor";
import renderVisitor from "@codama/renderers-js";
import { createFromRoot } from "codama";

export const SDK = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const IDL_DIR = join(SDK, "idl");
const TARGET_IDL = resolve(SDK, "..", "target", "idl");

/** Folder name in src/generated -> IDL file name. Order follows ProgramIdx. */
export const PROGRAM_IDLS = {
  registry: "deadroll_registry.json",
  render: "deadroll_render_program.json",
  character: "deadroll_character.json",
  items: "deadroll_items.json",
  map: "deadroll_map.json",
  session: "deadroll_session.json",
  city: "deadroll_city.json",
} as const;

export function copyIdls(): void {
  if (!existsSync(TARGET_IDL)) throw new Error(`no ${TARGET_IDL}: run anchor build first`);
  mkdirSync(IDL_DIR, { recursive: true });
  for (const file of Object.values(PROGRAM_IDLS)) copyFileSync(join(TARGET_IDL, file), join(IDL_DIR, file));
}

type IdlErrors = { errors?: { code: number; name: string; msg?: string }[] };

/**
 * `errors.ts`: code -> [IDL name, message] per program. Codama keeps only the codes and dev-build
 * messages, the app shows Anchor error names.
 */
function renderErrors(outDir: string): void {
  const lines = ["// Generated by sdk/scripts/generate.ts from sdk/idl. Do not edit.", ""];
  lines.push("export const PROGRAM_ERRORS = {");
  for (const [name, file] of Object.entries(PROGRAM_IDLS)) {
    const idl = JSON.parse(readFileSync(join(IDL_DIR, file), "utf8")) as IdlErrors;
    lines.push(`  ${name}: {`);
    for (const e of idl.errors ?? []) lines.push(`    ${e.code}: [${JSON.stringify(e.name)}, ${JSON.stringify(e.msg ?? "")}],`);
    lines.push("  },");
  }
  lines.push("} as const satisfies Record<string, Record<number, readonly [string, string]>>;", "");
  writeFileSync(join(outDir, "errors.ts"), lines.join("\n"));
}

export async function render(outDir: string): Promise<void> {
  mkdirSync(outDir, { recursive: true });
  renderErrors(outDir);
  for (const [name, file] of Object.entries(PROGRAM_IDLS)) {
    const idl = JSON.parse(readFileSync(join(IDL_DIR, file), "utf8")) as AnchorIdl;
    const codama = createFromRoot(rootNodeFromAnchor(idl));
    await codama.accept(
      renderVisitor(outDir, {
        generatedFolder: name,
        importExtension: "js",
        syncPackageJson: false,
      }),
    );
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const outAt = args.indexOf("--out");
  const out = outAt >= 0 ? resolve(args[outAt + 1]!) : join(SDK, "src", "generated");
  if (!args.includes("--no-copy")) copyIdls();
  await render(out);
  console.log(`generated ${Object.keys(PROGRAM_IDLS).length} programs into ${relative(SDK, out)}`);
}
